def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            q = [(r, c)]; seen.add((r, c)); comp = []
            while q:
                y, x = q.pop(); comp.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny, nx = y+dy, x+dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] != 0 and (ny,nx) not in seen:
                        seen.add((ny,nx)); q.append((ny,nx))
            components.append(comp)
    template = max(components, key=len)
    rs = [r for r,c in template]; cs = [c for r,c in template]
    r0, r1, c0, c1 = min(rs), max(rs), min(cs), max(cs)
    pattern = [[grid[r][c] for c in range(c0,c1+1)] for r in range(r0,r1+1)]
    ar, ac = (r1-r0)//2, (c1-c0)//2
    out = [row[:] for row in grid]
    for comp in components:
        if comp is template or len(comp) != 1:
            continue
        mr, mc = comp[0]
        for i,row in enumerate(pattern):
            for j,v in enumerate(row):
                y, x = mr+i-ar, mc+j-ac
                if v and 0 <= y < h and 0 <= x < w:
                    out[y][x] = v
    return out

