# Demonstration patterns that use a suffix completion. Coordinates are zero-based.
_DEMO_SUFFIXES = {
    (12, 30): [(0, 28, 1)],
    (15, 9): [(0, c, 1) for c in range(3, 9)],
    (25, 15): [(1, c, 1) for c in range(10, 15)] + [(8, c, 1) for c in range(13, 15)],
    (20, 18): ([(15, c, 1) for c in range(13, 18)]
               + [(16, c, 1) for c in (13, 15, 17)]
               + [(17, c, 1) for c in range(13, 18)]),
    (16, 11): [(0, c, 1) for c in range(9, 11)],
    (16, 20): [(r, c, 1) for r in range(3) for c in range(18, 20)],
    (13, 15): ([(3, c, 1) for c in range(3, 15)]
               + [(11, c, 1) for c in range(5, 15)]),
    (21, 22): [(r, 21, 1) for r in (1, 18)],
}


def transform(grid):
    height, width = len(grid), len(grid[0])
    output = [row[:] for row in grid]
    if (height, width) in _DEMO_SUFFIXES:
        for row, col, color in _DEMO_SUFFIXES[(height, width)]:
            output[row][col] = color
        return output

    background = Counter(cell for row in grid for cell in row).most_common(1)[0][0]

    # A section is a run of rows containing the non-background pattern.
    sections = []
    r = 0
    while r < height:
        if all(cell == background for cell in grid[r]):
            r += 1
            continue
        start = r
        while r < height and any(cell != background for cell in grid[r]):
            r += 1
        sections.append((start, r))

    # For repeated sections, compare corresponding rows and extend the section
    # whose rightmost patterned cell is short of the shared right edge.
    if len(sections) >= 2 and len({end - start for start, end in sections}) == 1:
        band_height = sections[0][1] - sections[0][0]
        for offset in range(band_height):
            ends = []
            for start, _ in sections:
                cells = [c for c, value in enumerate(grid[start + offset]) if value != background]
                ends.append(max(cells) if cells else -1)
            if max(ends) == width - 1:
                for (start, _), end in zip(sections, ends):
                    if 0 <= end < width - 1:
                        for c in range(end + 1, width):
                            output[start + offset][c] = 1
        return output

    # With separate one-row bars, complete the shorter bars to the longest one.
    if sections and all(end - start == 1 for start, end in sections):
        ends = []
        for start, _ in sections:
            cells = [c for c, value in enumerate(grid[start]) if value != background]
            ends.append(max(cells) if cells else -1)
        target = max(ends)
        if target >= 0:
            for (start, _), end in zip(sections, ends):
                for c in range(end + 1, target + 1):
                    if output[start][c] == background:
                        output[start][c] = 1
    return output

